args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?deathDate WHERE {
  VALUES ?person { dbr:Esther_Schiff_Goldfrank dbr:Kiliwehi }
  OPTIONAL {
    { ?person dbo:deathDate ?deathDate . }
    UNION
    { ?person dbp:deathDate ?deathDate . }
    UNION
    { ?person dbp:death_date ?deathDate . }
    UNION
    { ?person dbo:deathYear ?deathDate . }
    UNION
    { ?person dbp:deathYear ?deathDate . }
  }
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER (lang(?personLabel) = "en") }
}

